@jax.jit
def f(spikes, weight, seed):
    conn = brainevent.JITCScalarR((weight, 0.2, seed), shape=(8, 5))
    return brainevent.BinaryArray(spikes) @ conn

try:
    print(f(jnp.array([1,0,0,0,0,0,0,0], dtype=bool), 0.5, 3))
except Exception as exc:
    print(type(exc).__name__, exc)
